import{_ as a}from"./chunks/settings.zh.BbiDo0sw.js";import{_ as e,c as o,o as r,ae as i}from"./chunks/framework.BnYZi0O_.js";const s="/xiaozhi-mcphub/assets/smart-routing.zh.Bu6FD8Gi.png",_=JSON.parse('{"title":"智能路由","description":"","frontmatter":{},"headers":[],"relativePath":"features/smart-routing.md","filePath":"features/smart-routing.md"}'),d={name:"features/smart-routing.md"};function l(n,t,c,h,p,g){return r(),o("div",null,t[0]||(t[0]=[i('<h1 id="智能路由" tabindex="-1">智能路由 <a class="header-anchor" href="#智能路由" aria-label="Permalink to &quot;智能路由&quot;">​</a></h1><p>智能路由用向量语义检索，按用户请求只暴露最相关的 MCP 工具，降低上下文占用。客户端可使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:3000/mcp/$smart</span></span></code></pre></div><p><img src="'+s+'" alt="智能路由示意"></p><h2 id="启用条件" tabindex="-1">启用条件 <a class="header-anchor" href="#启用条件" aria-label="Permalink to &quot;启用条件&quot;">​</a></h2><ol><li>PostgreSQL <strong>带 pgvector</strong>（通常即 <code>DB_URL</code> 指向的库）</li><li>配置 Embedding：如 <code>OPENAI_API_KEY</code>、可选 <code>OPENAI_API_BASE_URL</code>、<code>OPENAI_API_EMBEDDING_MODEL</code></li><li>环境变量或设置中打开智能路由（如 <code>SMART_ROUTING_ENABLED=true</code>）</li></ol><h2 id="工作流程-简述" tabindex="-1">工作流程（简述） <a class="header-anchor" href="#工作流程-简述" aria-label="Permalink to &quot;工作流程（简述）&quot;">​</a></h2><ol><li><strong>索引</strong>：连接 MCP 服务器后，将工具名/描述等写入向量库</li><li><strong>检索</strong>：用户 prompt 向量化，top-k 相似工具</li><li><strong>暴露</strong>：仅相关工具进入上游模型上下文</li><li><strong>执行</strong>：仍由对应 MCP 服务器执行</li></ol><h2 id="多账户与配置-1-1-0" tabindex="-1">多账户与配置（1.1.0） <a class="header-anchor" href="#多账户与配置-1-1-0" aria-label="Permalink to &quot;多账户与配置（1.1.0）&quot;">​</a></h2><ul><li><strong>向量库连接 <code>dbUrl</code></strong>：实例级，<strong>仅管理员</strong>可在设置中查看/修改</li><li>普通用户可覆盖个人 smartRouting 相关项（如开关、个人 Key），经 <code>effectiveConfig</code> 与系统配置合并</li><li>小智端点可勾选「使用智能路由」，与 <code>$smart</code> 行为对齐</li></ul><h2 id="设置界面" tabindex="-1">设置界面 <a class="header-anchor" href="#设置界面" aria-label="Permalink to &quot;设置界面&quot;">​</a></h2><p>在 <strong>Settings</strong> 的 Smart Routing 区块配置；非管理员看不到/不能改全局 DB URL。</p><p><img src="'+a+'" alt="设置"></p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>检查</th></tr></thead><tbody><tr><td>无效果</td><td>客户端是否走 <code>/mcp/$smart</code>；功能是否启用</td></tr><tr><td>检索差</td><td>Embedding 模型与 Key；工具描述是否空洞</td></tr><tr><td>写入失败</td><td>pgvector 是否安装；DB 权限</td></tr></tbody></table>',15)]))}const b=e(d,[["render",l]]);export{_ as __pageData,b as default};
